WITH lines AS (SELECT order_id,SUM(quantity*unit_price_cents) AS cents FROM order_items GROUP BY order_id), pay AS (SELECT order_id,SUM(amount_cents) AS cents FROM payments GROUP BY order_id) SELECT o.order_id,COALESCE(l.cents,0)-COALESCE(p.cents,0) AS discrepancy_cents FROM orders o LEFT JOIN lines l ON l.order_id=o.order_id LEFT JOIN pay p ON p.order_id=o.order_id WHERE o.status='paid' AND COALESCE(l.cents,0)<>COALESCE(p.cents,0) ORDER BY o.order_id;
